package com.aistock.prediction.portfolioquestion;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.util.*;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;
class PortfolioAnswerTemplateTest {
 PortfolioQuestionRecords.Facts facts(){return PortfolioQuestionFacts.build(saved(),"解释浮盈","m",M);}
 ObjectNode answer(String topic,String...templates){var n=M.createObjectNode().put("status","ANSWERED").put("topic",topic);var a=n.putArray("paragraphs");for(String template:templates){var p=a.addObject().put("template",template);var refs=p.putArray("refs");var match=java.util.regex.Pattern.compile("\\{\\{([A-Z0-9_]+)\\}\\}").matcher(template);var set=new LinkedHashSet<String>();while(match.find())set.add(match.group(1));set.forEach(refs::add);}return n;}
 String base(){return "依据{{AS_OF}}保存记录，{{COVERAGE_LIMIT}}。{{DATE_LIMIT}}。{{FRESHNESS_LIMIT}}。{{BASIS_LIMIT}}。";}
 @Test void rendersOneOrTwoParagraphsAndKeepsReferenceAmounts(){var n=answer("PROFIT",base()+"{{PROFIT_RULE}}。{{S0001_PROFIT_STATE}}为{{S0001_PROFIT}}元。" );var a=PortfolioAnswerTemplate.render(n,facts(),M);assertEquals(1,a.paragraphs().size());assertTrue(a.paragraphs().get(0).path("text").asText().contains("500.00"));var b=answer("PROFIT",base(),"{{PROFIT_RULE}}。{{S0001_PROFIT}}元。");assertEquals(2,PortfolioAnswerTemplate.render(b,facts(),M).paragraphs().size());}
 @Test void rejectsZeroThreeParagraphsAndUnsafeLiterals(){for(String text:List.of("123元","上涨","浮亏","买入","<script>","{{NOT_KNOWN}}","{broken}")){assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("PROFIT",base()+text+"{{PROFIT_RULE}}"),facts(),M));}assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("PROFIT"),facts(),M));assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("PROFIT",base(),base(),base()),facts(),M));}
 @Test void missingOrExtraReferencesAndWrongRootAreRejected(){var n=answer("PROFIT",base()+"{{PROFIT_RULE}}");((ArrayNode)n.path("paragraphs").get(0).path("refs")).remove(0);assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(n,facts(),M));var extra=answer("PROFIT",base()+"{{PROFIT_RULE}}");extra.put("explanation","injected");assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(extra,facts(),M));}
 @Test void missingDatesAndTopicEvidenceAreRejected(){assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("PROFIT","{{PROFIT_RULE}}"),facts(),M));assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("CONCENTRATION",base()+"{{S0001_WEIGHT}}"),facts(),M));assertEquals("ANSWERED",PortfolioAnswerTemplate.render(answer("CONCENTRATION",base()+"{{S0001_WEIGHT}}，{{THRESHOLD}}。{{CONCENTRATION_RULE}}"),facts(),M).status());}
 @Test void partialCannotClaimFullPortfolioAndMustReferenceAllLimitations(){var f=PortfolioQuestionFacts.build(partial(),"限制","m",M);assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("COVERAGE","{{AS_OF}}，{{COVERAGE_LIMIT}}。{{BASIS_LIMIT}}"),f,M));assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(answer("CONCENTRATION",base()+"{{THRESHOLD}}。{{CONCENTRATION_RULE}}"),f,M));assertEquals("ANSWERED",PortfolioAnswerTemplate.render(answer("COVERAGE",base()),f,M).status());}
 @Test void outOfScopeIsControlledAndNoModelRefusalTextIsShown(){var n=M.createObjectNode().put("status","OUT_OF_SCOPE").put("topic","LIMITATION");n.putArray("paragraphs");var a=PortfolioAnswerTemplate.render(n,facts(),M);assertTrue(a.paragraphs().isEmpty());n.put("text","未经核验内容");assertThrows(Exception.class,()->PortfolioAnswerTemplate.render(n,facts(),M));}
 @Test void promptTreatsQuestionAsDataAndBudgetUsesFullEncodedUserMessage(){var f=facts();String system=PortfolioQuestionPrompt.build(f.values());assertFalse(system.contains("IGNORE_PRIVATE_RULES"));assertDoesNotThrow(()->PortfolioQuestionPrompt.checkBudget("风险",f.values(),M,65536));assertThrows(Exception.class,()->PortfolioQuestionPrompt.checkBudget("风险",f.values(),M,20));assertTrue(system.contains("status"));}
}
